import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

// 1. Create a class to hold your state. It must extend ChangeNotifier.
class CounterModel extends ChangeNotifier {  int _count = 0;
	int get count => _count;

	void increment() {
		_count++;
		notifyListeners(); // Tell listening widgets to rebuild.
	}
}void main() {
	runApp(
		// 2. Provide the model to the widget tree.
		ChangeNotifierProvider(
			create: (context) => CounterModel(),
			child: const MyApp(),
		),
	);
}class MyApp extends StatelessWidget {
const MyApp({Key? key}) : super(key: key);

   @override
	Widget build(BuildContext context) {    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(title: Text('Provider Demo')),
        body: Center(
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              // 3. Create a widget that consumes the state.
              Consumer<CounterModel>(
                builder: (context, counter, child) {
                  return Text(
                    'Count: ${counter.count}',
                    style: Theme.of(context).textTheme.headlineMedium,
                  );
                },
              ),
              SizedBox(height: 20),
              // Get the model to call a method (but don't rebuild this widget).
              ElevatedButton(
                onPressed: () => context.read<CounterModel>().increment(),
                child: Text('Increment'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

