import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

// 1. Declare a provider globally.
// StateProvider is great for simple state like enums, strings, bools, or numbers.
final counterProvider = StateProvider<int>((ref) => 0);

void main() {
  // 2. Wrap the root widget with ProviderScope.
  runApp(const ProviderScope(child: MyApp()));
}

// 3. Extend ConsumerWidget instead of StatelessWidget.
class MyApp extends ConsumerWidget {
  const MyApp({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    // 4. Use 'ref' to interact with providers.
    // ref.watch() makes the widget listen for changes.
    final count = ref.watch(counterProvider);

    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(title: Text('Riverpod Demo')),
        body: Center(
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                'Count: $count',
                style: Theme.of(context).textTheme.headlineMedium,
              ),
              SizedBox(height: 20),
              ElevatedButton(
                // ref.read() gets the provider's notifier to call methods.
                onPressed: () => ref.read(counterProvider.notifier).state++,
                child: Text('Increment'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
